function campaignState(key, ledger, dryRun) {
  const records = ledger.filter(r => String(r.CampaignKey || '').trim() === key);
  if (records.length > 1) throw new Error('Duplicate CampaignKey in campaign log: ' + key);
  const record = records[0];
  if (!record) return null;
  const status = String(record.Status || '').toLowerCase();
  const stop = reason => ({ ready: false, campaignKey: key, status: 'nothing_to_render', reason, videoUrl: record.VideoUrl || null });
  if (record.VideoUrl || status === 'completed') return stop('This campaign is already complete. Use its saved video; create a new campaign key only for an intentional new campaign.');
  if (['submitting', 'failed', 'timed_out', 'needs_review'].includes(status)) return stop('Inspect the saved campaign in Zvid before clearing its uncertain or failed state.');
  if (record.JobId) {
    if (dryRun) return stop('Preview skips an existing paid job. Set dryRun=false to resume it.');
    let plan;
    try { plan = JSON.parse(record.PlanJson); } catch { throw new Error('Saved campaign PlanJson is missing or invalid; inspect the existing job instead of resubmitting.'); }
    if (!plan.payload || plan.campaignKey !== key) throw new Error('Saved campaign snapshot does not match its key.');
    return { ...plan, ready: true, jobId: String(record.JobId), creditsRequired: Number(record.CreditsQuoted), resumed: true };
  }
  throw new Error('Campaign key already exists without a recoverable job. Inspect the log before deliberately clearing that row.');
}
function trackedLink(raw, campaign, content) {
  const url = String(raw || '').trim();
  if (!/^https:\/\/[a-z0-9.-]+(?::\d+)?(?:[/?#][^\s]*)?$/i.test(url)) throw new Error('A public HTTPS application or booking URL is required.');
  const hash = url.indexOf('#'), fragment = hash < 0 ? '' : url.slice(hash), base = hash < 0 ? url : url.slice(0, hash);
  const q = base.indexOf('?'), path = q < 0 ? base : base.slice(0, q);
  const query = (q < 0 ? '' : base.slice(q + 1)).split('&').filter(Boolean).filter(p => !/^utm_(source|medium|campaign|content)=/i.test(p));
  query.push('utm_source=social', 'utm_medium=video', 'utm_campaign=' + encodeURIComponent(campaign), 'utm_content=' + encodeURIComponent(content));
  return path + '?' + query.join('&') + fragment;
}
function planRestaurant(cfg, rows, ledger, now) {
  const text = v => String(v ?? '').trim(), yes = v => ['true','yes','1','x'].includes(text(v).toLowerCase());
  const today = new Intl.DateTimeFormat('en-CA', { timeZone: cfg.timezone || 'UTC', year: 'numeric', month: '2-digit', day: '2-digit' }).format(now);
  const monday = new Date(today + 'T12:00:00Z'); monday.setUTCDate(monday.getUTCDate() - (monday.getUTCDay() + 6) % 7);
  const addDays = n => { const d = new Date(monday); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0,10); };
  const weekStart = addDays(0), weekEnd = addDays(6), revision = text(cfg.campaignRevision || '1');
  if (!/^[a-zA-Z0-9_-]{1,24}$/.test(revision)) throw new Error('campaignRevision must be a short letter/number/underscore/hyphen value.');
  const key = 'menu-' + weekStart + '-' + revision;
  const previous = campaignState(key, ledger, cfg.dryRun === true);
  if (previous) return previous;
  const max = Math.floor(Number(cfg.maxDishes ?? 5)), min = Math.floor(Number(cfg.minDishes ?? 3)), minCategories = Math.floor(Number(cfg.minCategories ?? 2));
  if (![max,min,minCategories].every(Number.isFinite) || min < 1 || max > 5 || max < min || minCategories < 1 || minCategories > max) throw new Error('Require 1 <= minDishes <= maxDishes <= 5 and minCategories <= maxDishes.');
  const lastKeys = new Set();
  for (const record of ledger.filter(r => r.Status === 'completed')) {
    try { const plan = JSON.parse(record.PlanJson); if (plan.weekStart === addDays(-7)) for (const d of plan.dishes || []) lastKeys.add(d.key); } catch { /* Old unrelated log rows do not define menu history. */ }
  }
  const date = (v, name) => { const s = text(v); if (s && (!/^\d{4}-\d{2}-\d{2}$/.test(s) || !Number.isFinite(Date.parse(s)) || new Date(s).toISOString().slice(0,10) !== s)) throw new Error(name + ' must be a real YYYY-MM-DD date.'); return s; };
  const seen = new Set(), skipped = [], eligible = [];
  for (const row of rows.filter(r => text(r.DishKey) || text(r.Dish))) {
    const id = text(row.DishKey);
    if (!id || seen.has(id)) throw new Error('Every menu row needs a unique DishKey.');
    seen.add(id);
    const from = date(row.AvailableFrom, id + ' AvailableFrom'), until = date(row.AvailableUntil, id + ' AvailableUntil');
    if (from && until && from > until) throw new Error(id + ': AvailableFrom is after AvailableUntil.');
    let reason = '';
    if (!yes(row.ThisWeek)) reason = 'not_nominated';
    else if (text(row.Approval).toLowerCase() !== 'approved') reason = 'awaiting_menu_approval';
    else if (!yes(row.InStock)) reason = 'unavailable';
    else if ((from && from > weekStart) || (until && until < weekEnd)) reason = 'not_available_for_entire_campaign_week';
    else if (![row.Dish,row.Category,row.Price].every(v => text(v))) reason = 'missing_dish_category_or_price';
    else if (text(row.Dish).length > 70 || text(row.Description).length > 180 || text(row.Price).length > 18) reason = 'copy_exceeds_card_limits';
    else if (!/^https:\/\/[^\s]+$/i.test(text(row.PhotoUrl))) reason = 'missing_https_dish_photo';
    if (reason) { skipped.push({ key: id, reason }); continue; }
    eligible.push({ key:id, name:text(row.Dish), category:text(row.Category), description:text(row.Description), price:text(row.Price), photo:text(row.PhotoUrl), priority:Number(row.Priority) || 0, featuredLastWeek:lastKeys.has(id) });
  }
  eligible.sort((a,b) => b.priority-a.priority || Number(a.featuredLastWeek)-Number(b.featuredLastWeek) || a.key.localeCompare(b.key));
  const picked = [], categories = new Set();
  for (const d of eligible) if (!categories.has(d.category.toLowerCase()) && picked.length < max) { picked.push(d); categories.add(d.category.toLowerCase()); }
  for (const d of eligible) if (!picked.includes(d) && picked.length < max) picked.push(d);
  if (picked.length < min || categories.size < minCategories) return { ready:false, campaignKey:key, status:'menu_needs_revision', reason:'Not enough approved, available dishes or category variety for this weekly campaign.', eligibleCount:eligible.length, categoryCount:categories.size, requiredDishes:min, requiredCategories:minCategories, skipped };
  const bookingUrl = trackedLink(cfg.bookingUrl, key, 'weekly-menu');
  const weekLabel = 'WEEK OF ' + weekStart;
  const menu = picked.map(d => d.name + ' · ' + d.price).join('\n');
  const caption = [cfg.restaurantName + ' · ' + weekLabel, menu, 'Available ' + weekStart + ' to ' + weekEnd + ', while available.', 'Reserve: ' + bookingUrl].join('\n\n');
  const posts = [
    {date:addDays(0),purpose:'Weekly menu launch',caption},
    {date:addDays(2),purpose:'Midweek dish spotlight',caption:[picked[0].name + ' · ' + picked[0].price,picked[0].description,'On the menu through ' + weekEnd,'Reserve: ' + trackedLink(cfg.bookingUrl,key,'midweek-' + picked[0].key)].filter(Boolean).join('\n\n')},
    {date:addDays(4),purpose:'Weekend reservation reminder',caption:[cfg.restaurantName + ' · Make a plan for the weekend',menu,'This week’s menu ends ' + weekEnd,'Reserve: ' + trackedLink(cfg.bookingUrl,key,'weekend')].join('\n\n')},
  ].map(p => ({...p,reviewStatus:p.date < today ? 'past_date_do_not_publish' : 'review_before_scheduling'}));
  return {ready:true,campaignKey:key,weekStart,weekEnd,weekLabel,dishes:picked,bookingUrl,caption,posts,skipped,deferredDishKeys:eligible.filter(d=>!picked.includes(d)).map(d=>d.key),jobId:null,creditsRequired:0};
}
const cfg=$('Set weekly menu campaign rules').first().json;
return [{json:planRestaurant(cfg,$('Read nominated menu dishes').all().map(i=>i.json),$input.all().map(i=>i.json),new Date())}];

function fitMenuImageUrl(value) {
  const src = String(value || '').trim();
  // Both bundled image hosts support aspect-preserving bounds. Leave other
  // customer and signed URLs byte-for-byte unchanged.
  const match = /^(https:\/\/images\.(?:pexels\.com|unsplash\.com)\/[^?#]+)(?:\?([^#]*))?(#.*)?$/i.exec(src);
  if (!match) return src;
  const params = (match[2] || '').split('&').filter(Boolean)
    .filter(part => !/^(?:w|h|fit|dpr)=/i.test(part));
  return match[1] + '?' + [...params, 'w=1920', 'h=1920', 'fit=max', 'dpr=1'].join('&') + (match[3] || '');
}

// Builder for the "Restaurant weekly specials" Zvid project.
// Adapted from the local-menu-promo / pro-local-menu-promo / local-top-5-dishes
// library examples: full-bleed sizzle hook, one photo card per dish, CTA endcard.
// The EXACT same logic is embedded in the n8n workflow's "Build project JSON"
// code node — keep the two in sync.

// ---------- tiny helpers -------------------------------------------------
const escapeHtml = (s) =>
  String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

const round = (n) => Math.round(n * 100) / 100;

const hexToRgba = (hex, a) => {
  const m = /^#?([0-9a-f]{6})$/i.exec(String(hex).trim());
  if (!m) return `rgba(232,106,51,${a})`;
  const n = parseInt(m[1], 16);
  return `rgba(${(n >> 16) & 255},${(n >> 8) & 255},${n & 255},${a})`;
};

const lighten = (hex, amt) => {
  const m = /^#?([0-9a-f]{6})$/i.exec(String(hex).trim());
  if (!m) return hex;
  const n = parseInt(m[1], 16);
  const ch = (v) => Math.max(0, Math.min(255, v + amt)).toString(16).padStart(2, '0');
  return `#${ch((n >> 16) & 255)}${ch((n >> 8) & 255)}${ch(n & 255)}`;
};

// Auto week label: "WEEK OF JUL 27" for the Monday of the current week.
const autoWeekLabel = (now = new Date()) => {
  const d = new Date(now.getTime());
  d.setDate(d.getDate() - ((d.getDay() + 6) % 7)); // back to Monday
  const months = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'];
  return `WEEK OF ${months[d.getMonth()]} ${d.getDate()}`;
};

// ---------- main ---------------------------------------------------------
function buildProject(cfg, dishesInput) {
  const bg = cfg.brandBg || '#180F0A';
  const accent = cfg.brandAccent || '#E86A33';
  const cream = cfg.brandCream || '#FFF4E8';
  const muted = cfg.brandMuted || '#E4CBB0';
  const headFont = cfg.headlineFont || 'Bebas Neue';
  const bodyFont = cfg.bodyFont || 'DM Sans';

  const maxDishes = Math.max(1, Math.min(5, Number(cfg.maxDishes ?? 5)));

  // -- dishes: validate, trim, fall back ---------------------------------
  const fallbacks = Array.isArray(cfg.fallbackDishPhotos) ? cfg.fallbackDishPhotos.filter(Boolean) : [];
  const raw = Array.isArray(dishesInput) ? dishesInput : [];
  const dishes = raw
    .map((d) => ({
      name: String(d.name ?? '').trim(),
      description: String(d.description ?? '').trim(),
      price: String(d.price ?? '').trim(),
      photo: String(d.photo ?? '').trim(),
    }))
    .filter((d) => d.name);

  if (!dishes.length) {
    throw new Error(
      'No dishes to feature. Mark 1-5 rows with ThisWeek = TRUE in the menu sheet (columns: Dish, Description, Price, PhotoUrl, ThisWeek).'
    );
  }
  const skipped = Math.max(0, dishes.length - maxDishes);
  const picked = dishes.slice(0, maxDishes);

  picked.forEach((d, i) => {
    if (!/^https?:\/\//i.test(d.photo)) {
      d.photo = fallbacks.length ? fallbacks[i % fallbacks.length] : '';
    }
    if (!d.photo) throw new Error(`Dish "${d.name}" has no PhotoUrl and no fallback photo is configured.`);
    d.photo = fitMenuImageUrl(d.photo);
    // Keep descriptions to ~3 lines on the card.
    if (d.description.length > 220) d.description = d.description.slice(0, 217).trimEnd() + '…';
  });

  const weekLabel = String(cfg.weekLabel || '').trim() || autoWeekLabel();

  // -- timing ------------------------------------------------------------
  const hookSeconds = Number(cfg.hookSeconds ?? 3);
  const dishSeconds = Number(cfg.dishSeconds ?? 2.8);
  const ctaSeconds = Number(cfg.ctaSeconds ?? 3.4);

  // -- adaptive font sizes (long names must not clip) --------------------
  const nameLen = (cfg.restaurantName || '').length;
  const brandFs = nameLen <= 20 ? 38 : nameLen <= 32 ? 31 : 26;
  const brandLs = nameLen <= 20 ? 10 : nameLen <= 32 ? 6 : 4;

  const hookTitle = cfg.hookTitle || "This week's specials";
  const hookFs = hookTitle.length <= 20 ? 132 : hookTitle.length <= 30 ? 106 : 86;

  const ctaHeadline = cfg.ctaHeadline || 'Hungry yet?';
  const ctaFs = ctaHeadline.length <= 14 ? 96 : ctaHeadline.length <= 24 ? 78 : 62;

  const dishNameFs = (n) => (n.length <= 16 ? 104 : n.length <= 26 ? 88 : n.length <= 40 ? 72 : 58);

  const accentBorder = hexToRgba(accent, 0.4);
  const accentSoft = hexToRgba(accent, 0.7);

  // -- SVG overlays ------------------------------------------------------
  const hookSvg =
    `<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'>` +
    `<defs><linearGradient id='rwsHook' x1='0' y1='0' x2='0' y2='1'>` +
    `<stop offset='0' stop-color='${bg}' stop-opacity='0.55'/>` +
    `<stop offset='0.42' stop-color='${bg}' stop-opacity='0.12'/>` +
    `<stop offset='0.68' stop-color='${bg}' stop-opacity='0.5'/>` +
    `<stop offset='1' stop-color='${bg}' stop-opacity='0.92'/>` +
    `</linearGradient></defs>` +
    `<rect width='1080' height='1920' fill='url(#rwsHook)'/>` +
    `<path d='M84 300 L84 116 L268 116' fill='none' stroke='${cream}' stroke-width='9' stroke-opacity='0.9'/>` +
    `<path d='M996 1624 L996 1808 L812 1808' fill='none' stroke='${accent}' stroke-width='9'/>` +
    `<circle cx='940' cy='300' r='7' fill='${accent}'/>` +
    `</svg>`;

  const dishSvg = (idx) =>
    `<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'>` +
    `<defs><linearGradient id='rwsDish${idx}' x1='0' y1='0' x2='0' y2='1'>` +
    `<stop offset='0' stop-color='${bg}' stop-opacity='0.42'/>` +
    `<stop offset='0.4' stop-color='${bg}' stop-opacity='0.06'/>` +
    `<stop offset='0.68' stop-color='${bg}' stop-opacity='0.55'/>` +
    `<stop offset='1' stop-color='${bg}' stop-opacity='0.96'/>` +
    `</linearGradient></defs>` +
    `<rect width='1080' height='1920' fill='url(#rwsDish${idx})'/>` +
    `<rect x='46' y='46' width='988' height='1828' rx='30' fill='none' stroke='${accentBorder}' stroke-width='1.5'/>` +
    `</svg>`;

  const ctaSvg =
    `<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'>` +
    `<defs><radialGradient id='rwsCta' cx='0.5' cy='0.4' r='0.9'>` +
    `<stop offset='0' stop-color='${lighten(bg, 22)}'/>` +
    `<stop offset='1' stop-color='${bg}'/>` +
    `</radialGradient></defs>` +
    `<rect width='1080' height='1920' fill='url(#rwsCta)'/>` +
    `<rect x='46' y='46' width='988' height='1828' rx='34' fill='none' stroke='${accentBorder}' stroke-width='2'/>` +
    `<path d='M470 560 C470 610 610 610 610 560 M450 560 H630 L610 760 C608 780 472 780 470 760 Z' fill='none' stroke='${accent}' stroke-width='7' stroke-linejoin='round'/>` +
    `<path d='M505 500 C505 480 520 480 520 460 M545 500 C545 480 560 480 560 460 M585 500 C585 480 600 480 600 460' stroke='${accentSoft}' stroke-width='6' stroke-linecap='round' fill='none'/>` +
    `</svg>`;

  // -- scene 1: sizzle hook ----------------------------------------------
  const scenes = [];
  scenes.push({
    id: 'hook',
    duration: hookSeconds,
    backgroundColor: bg,
    transition: 'fade',
    transitionId: 'dish-1',
    transitionDuration: 0.5,
    visuals: [
      {
        type: 'VIDEO',
        src: cfg.sizzleVideo,
        width: 1080,
        height: 1920,
        position: 'center-center',
        resize: 'cover',
        volume: 0,
        track: 0,
        enterBegin: 0,
        exitEnd: hookSeconds,
      },
      { type: 'SVG', width: 1080, height: 1920, track: 1, enterBegin: 0, exitEnd: hookSeconds, svg: hookSvg },
      {
        type: 'TEXT',
        x: 540,
        y: 150,
        width: 940,
        anchor: 'top-center',
        track: 2,
        enterBegin: 0.2,
        enterEnd: 0.6,
        enterAnimation: 'fade',
        exitEnd: hookSeconds,
        style: { fontFamily: headFont, color: cream },
        html: `<div style='text-align:center; color:${cream}; font-size:${brandFs}px; letter-spacing:${brandLs}px;'>${escapeHtml(cfg.restaurantName)}</div>`,
      },
      {
        type: 'TEXT',
        x: 90,
        y: 1500,
        width: 900,
        anchor: 'bottom-left',
        track: 3,
        enterBegin: 0.4,
        enterEnd: 0.85,
        enterAnimation: 'smoothup',
        exitEnd: hookSeconds,
        style: { fontFamily: headFont, color: cream },
        html:
          `<div style='display:inline-block; background:${accent}; color:${cream}; border-radius:999px; padding:14px 34px; font-size:27px; font-weight:800; letter-spacing:4px; font-family:${bodyFont}, sans-serif;'>${escapeHtml(weekLabel)}</div>` +
          `<div style='margin-top:26px; color:${cream}; font-size:${hookFs}px; line-height:0.98; letter-spacing:2px;'>${escapeHtml(hookTitle)}</div>`,
      },
      {
        type: 'TEXT',
        x: 90,
        y: 1560,
        width: 900,
        anchor: 'top-left',
        track: 4,
        enterBegin: 0.65,
        enterEnd: 1.1,
        enterAnimation: 'smoothup',
        exitEnd: hookSeconds,
        style: { fontFamily: bodyFont, color: muted },
        html: `<div style='color:${muted}; font-size:${(cfg.tagline || '').length > 60 ? 26 : 30}px; line-height:1.35; font-weight:600;'>${escapeHtml(cfg.tagline || '')}</div>`,
      },
    ],
  });

  // -- one card per dish --------------------------------------------------
  picked.forEach((dish, i) => {
    const idx = i + 1;
    const isLast = i === picked.length - 1;
    const counter = picked.length > 1 ? `SPECIAL ${idx} OF ${picked.length}` : "THIS WEEK'S SPECIAL";
    const priceFs = dish.price.length > 7 ? 34 : 40;

    const visuals = [
      {
        type: 'IMAGE',
        src: dish.photo,
        width: 1080,
        height: 1920,
        position: 'center-center',
        resize: 'cover',
        zoom: true,
        track: 0,
        enterBegin: 0,
        exitEnd: dishSeconds,
      },
      { type: 'SVG', width: 1080, height: 1920, track: 1, enterBegin: 0, exitEnd: dishSeconds, svg: dishSvg(idx) },
      {
        type: 'TEXT',
        x: 90,
        y: 150,
        anchor: 'top-left',
        track: 2,
        enterBegin: 0.15,
        enterEnd: 0.5,
        enterAnimation: 'smoothleft',
        exitEnd: dishSeconds,
        style: { fontFamily: bodyFont, color: cream },
        html: `<div style='display:inline-block; background:${accent}; color:${cream}; border-radius:999px; padding:14px 34px; font-size:26px; font-weight:800; letter-spacing:3px;'>${escapeHtml(counter)}</div>`,
      },
      {
        type: 'TEXT',
        x: 90,
        y: 1620,
        width: 900,
        anchor: 'bottom-left',
        track: 3,
        enterBegin: 0.35,
        enterEnd: 0.8,
        enterAnimation: 'smoothup',
        exitEnd: dishSeconds,
        style: { fontFamily: headFont, color: cream },
        html:
          `<div style='color:${cream}; font-size:${dishNameFs(dish.name)}px; line-height:0.98; letter-spacing:2px;'>${escapeHtml(dish.name)}</div>` +
          (dish.description
            ? `<div style='margin-top:16px; font-family:${bodyFont}, sans-serif; color:${muted}; font-size:29px; line-height:1.42; font-weight:500;'>${escapeHtml(dish.description)}</div>`
            : ''),
      },
    ];

    if (dish.price) {
      visuals.push({
        type: 'TEXT',
        x: 880,
        y: 205,
        anchor: 'center-center',
        angle: -6,
        track: 4,
        enterBegin: 0.55,
        enterEnd: 0.9,
        enterAnimation: 'circleopen',
        exitEnd: dishSeconds,
        style: { fontFamily: bodyFont, color: cream },
        html: `<div style='display:inline-block; background:${cream}; color:${bg}; border-radius:18px; padding:14px 36px; font-size:${priceFs}px; font-weight:800;'>${escapeHtml(dish.price)}</div>`,
      });
    }

    scenes.push({
      id: `dish-${idx}`,
      duration: dishSeconds,
      backgroundColor: bg,
      transition: isLast ? 'smoothup' : 'fade',
      transitionId: isLast ? 'cta' : `dish-${idx + 1}`,
      transitionDuration: isLast ? 0.5 : 0.45,
      visuals,
    });
  });

  // -- CTA endcard ---------------------------------------------------------
  const ctaVisuals = [
    { type: 'SVG', width: 1080, height: 1920, track: 0, enterBegin: 0, exitEnd: ctaSeconds, svg: ctaSvg },
    {
      type: 'TEXT',
      x: 540,
      y: 900,
      width: 940,
      anchor: 'top-center',
      track: 1,
      enterBegin: 0.25,
      enterEnd: 0.7,
      enterAnimation: 'smoothup',
      exitEnd: ctaSeconds,
      style: { fontFamily: headFont, color: cream },
      html: `<div style='text-align:center; color:${cream}; font-size:${ctaFs}px; line-height:1; letter-spacing:2px;'>${escapeHtml(ctaHeadline)}</div>`,
    },
    {
      type: 'TEXT',
      x: 540,
      y: 1120,
      anchor: 'top-center',
      track: 2,
      enterBegin: 0.65,
      enterEnd: 1.05,
      enterAnimation: 'circleopen',
      exitEnd: ctaSeconds,
      style: { fontFamily: bodyFont, color: cream },
      html: `<div style='display:inline-block; background:${accent}; color:${cream}; border-radius:999px; padding:26px 62px; font-size:36px; font-weight:800;'>${escapeHtml(cfg.ctaText || 'Book a table')}</div>`,
    },
    {
      type: 'TEXT',
      x: 540,
      y: 1300,
      width: 900,
      anchor: 'top-center',
      track: 3,
      enterBegin: 0.95,
      enterEnd: 1.35,
      enterAnimation: 'fade',
      exitEnd: ctaSeconds,
      style: { fontFamily: bodyFont, color: cream },
      html:
        `<div style='text-align:center; color:${cream}; font-size:30px; font-weight:700;'>${escapeHtml(cfg.handle || '')}</div>` +
        `<div style='margin-top:10px; text-align:center; color:${muted}; font-size:26px; font-weight:500;'>${escapeHtml(cfg.address || '')}</div>`,
    },
    {
      type: 'TEXT',
      x: 540,
      y: 1460,
      width: 900,
      anchor: 'top-center',
      track: 4,
      enterBegin: 1.15,
      enterEnd: 1.55,
      enterAnimation: 'fade',
      exitEnd: ctaSeconds,
      style: { fontFamily: headFont, color: cream },
      html: `<div style='text-align:center; color:${hexToRgba(cream, 0.55)}; font-size:25px; letter-spacing:6px;'>${escapeHtml(cfg.deliveryNote || '')}</div>`,
    },
  ];

  scenes.push({ id: 'cta', duration: ctaSeconds, backgroundColor: bg, visuals: ctaVisuals });

  // -- assemble -----------------------------------------------------------
  const overlaps = scenes.reduce((s, sc) => s + (sc.transitionDuration || 0), 0);
  const totalDuration = round(scenes.reduce((s, sc) => s + sc.duration, 0) - overlaps);

  // The API accepts ASCII letters/digits/space/_/- only in project names.
  const safeName =
    (String(cfg.restaurantName || 'restaurant')
      .toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '')
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '')
      .slice(0, 44) || 'restaurant') + '-weekly-specials';

  const payload = {
    name: safeName,
    resolution: cfg.resolution || 'instagram-reel',
    frameRate: Number(cfg.frameRate ?? 30),
    backgroundColor: bg,
    outputFormat: 'mp4',
    scenes,
    // NOTE: no `track` on audios — the public API rejects it.
    audios: cfg.musicUrl ? [{ src: cfg.musicUrl, volume: Number(cfg.musicVolume ?? 0.18) }] : [],
  };

  return {
    payload,
    meta: {
      weekLabel,
      dishCount: picked.length,
      skippedDishes: skipped,
      dishNames: picked.map((d) => d.name),
      totalDuration,
      sceneBreakdown: scenes.map((s, i) => `${i + 1}. ${s.id} — ${s.duration}s`).join('\n'),
    },
  };
}

